before:
/** 🛡️ Independent RFC6902 refusal conservation before an undeclared prepared owner is touched. */
import {test,expect} from "bun:test";
import {applyPatch} from "fast-json-patch";
import {readFileSync} from "node:fs";
import fixture from "../../🧫️fixtures/📦️prepared-close/🔣️.json" with {type:"json"};
test("prepared job refuses undeclared close authority without converting release into copy receipts",()=>{
 for(const grant of fixture.grants){
  const original=structuredClone(fixture.retained),after=applyPatch(original,[],true).newDocument;
  expect(after).toEqual(fixture.retained);
  expect(fixture.expectedRetained.copiedItems+fixture.expectedRetained.copiedBytes+fixture.expectedRetained.retainedCapacityBytes+fixture.expectedRetained.releasedBytes).toBe(0);
 }
 const source=readFileSync(new URL("../../🎯️targets/🧊️wgpu/🎟️prepared/🦀️.rs",import.meta.url),"utf8");
 const adapter=source.slice(source.indexOf("impl InteractiveJob for PreparedRenderJob"),source.indexOf("//#endregion ⚙️PreparationJob"));
 expect(adapter).toContain("grant: semio_framework_job::RetainedCloneGrant");
 expect(adapter).toContain("ValueRefusalKind::UnsupportedOwner");
 expect(adapter).not.toContain("PreparedRenderJob::close_step(self)");
 console.log(`[DEBUG] prepared close grants=${fixture.grants.length} retainedOwner=true work=0 capacity=0 release=0 unsupportedExplicit=true`);
});

after:
/** 🛡️ Independent schema and RFC6902 ownership conservation at a declared prepared frontier. */
import {test,expect} from "bun:test";
import Ajv2020 from "ajv/dist/2020";
import {applyPatch} from "fast-json-patch";
import {readFileSync} from "node:fs";
import fixture from "../../🧫️fixtures/📦️prepared-close/🔣️.json" with {type:"json"};
import schema from "../../🧬️schema/📦️prepared-close/🔣️.json" with {type:"json"};
test("prepared job preserves original input through independently funded declared close",()=>{
 const validate=new Ajv2020({strict:true}).compile(schema);
 expect(validate(fixture)).toBe(true);
 for(const grant of fixture.grants){
  const after=applyPatch(structuredClone(fixture.retained),grant.items===0?[]:[{op:"replace",path:"/commands",value:false}],true).newDocument;
  expect(after).toEqual({input:true,commands:grant.commandsRetained,receiver:true});
  expect(grant.expectedItems).toBe(grant.items===0?0:1);
 }
 expect(fixture.expectedTerminal).toEqual({result:"complete",copiedItems:0,copiedBytes:0,retainedCapacityBytes:0,releasedBytes:0});
 const source=readFileSync(new URL("../../🎯️targets/🧊️wgpu/🎟️prepared/🦀️.rs",import.meta.url),"utf8");
 const job=source.slice(source.indexOf("impl InteractiveJob for PreparedRenderJob"),source.indexOf("//#endregion ⚙️PreparationJob"));
 expect(job).toContain("grant: RetainedCloneGrant");
 expect(job).toContain("self.close_granted(grant)");
 expect(job).toContain("next_close_release_byte_demand");
 expect(job).not.toContain("UnsupportedOwner");
 console.log(`[DEBUG] prepared close grants=${fixture.grants.length} schema=true independentRFC6902=true originalInput=true axesIndependent=true`);
});
